mapper.select:
select t.port_type,t.port_type portType,t.port,t.create_time,t.create_time
createTime,t.remark,t.status_cd,t.status_cd statusCd,t.platform_id,t.platform_id
platformId,t.community_id,t.community_id communityId,t.platform_name,t.platform_name
platformName,t.ip_addr,t.ip_addr ipAddr
from calling_platform t
where 1 =1

    and t.port_type= #{portType}


    and t.port= #{port}


    and t.create_time= #{createTime}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.platform_id= #{platformId}


    and t.community_id= #{communityId}


    and t.platform_name= #{platformName}


    and t.ip_addr= #{ipAddr}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update calling_platform t set t.status_cd = #{statusCd}

    , t.port_type= #{portType}


    , t.port= #{port}


    , t.create_time= #{createTime}


    , t.remark= #{remark}


    , t.community_id= #{communityId}


    , t.platform_name= #{platformName}


    , t.ip_addr= #{ipAddr}

where 1=1

    and t.platform_id= #{platformId}

